import{_ as e,o,c as a,ag as i}from"./chunks/framework.wGDfT7ie.js";const d=JSON.parse('{"title":"Why it matters","description":"","frontmatter":{},"headers":[],"relativePath":"why.md","filePath":"why.md"}'),r={name:"why.md"};function s(n,t,l,c,h,p){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="why-it-matters" tabindex="-1">Why it matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why it matters&quot;">​</a></h1><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>DeFi today forces a choice:</p><ul><li><strong>Full transparency</strong> — Everyone can see your positions, sizes, timing, and counterparties. That exposes you to front-running, copy-trading, and loss of edge.</li><li><strong>Opaque custody</strong> — You hand over control to a custodian or fund. You get privacy but lose verifiability: you must trust that they followed the rules.</li></ul><p>We want <strong>privacy-preserving execution that is verifiable</strong>. You keep control; the system proves that it followed your constraints without revealing the details.</p><h2 id="our-approach" tabindex="-1">Our approach <a class="header-anchor" href="#our-approach" aria-label="Permalink to &quot;Our approach&quot;">​</a></h2><p><strong>zkde.fi</strong> gives you:</p><ol><li><strong>Verifiable execution</strong> — Every action is proof-gated. The chain only accepts transactions that come with a valid proof (e.g. that your allocation stayed within limits). No proof, no execution.</li><li><strong>Privacy</strong> — Intent is hidden until execution. Balances can be confidential (commitment-based). You can prove specific statements (compliance, eligibility) without exposing your full history.</li><li><strong>You stay in control</strong> — You set constraints and delegate via session keys. The agent operates within those limits; you can revoke or tighten them anytime.</li></ol><p>Result: autonomous, privacy-preserving DeFi that stays auditable and trustless.</p><p>Next: <a href="/docs/concepts.html">Key concepts</a></p>',10)])])}const y=e(r,[["render",s]]);export{d as __pageData,y as default};
